fn normalize_allowed_tools(values: &[String]) -> Result<Option<AllowedToolSet>, String> {
    if values.is_empty() {
        return Ok(None);
    }
    current_tool_registry()?.normalize_allowed_tools(values)
}

fn current_tool_registry() -> Result<GlobalToolRegistry, String> {
    let cwd = env::current_dir().map_err(|error| error.to_string())?;
    let loader = ConfigLoader::default_for(&cwd);
    let runtime_config = loader.load().map_err(|error| error.to_string())?;
    let plugin_manager = build_plugin_manager(&cwd, &loader, &runtime_config);
    let plugin_tools = match plugin_manager.aggregated_tools() {
        Ok(tools) => tools,
        Err(error) if should_fallback_to_builtin_tool_registry(&error) => Vec::new(),
        Err(error) => return Err(error.to_string()),
    };
    GlobalToolRegistry::with_plugin_tools(plugin_tools)
}

fn should_fallback_to_builtin_tool_registry(error: &PluginError) -> bool {
    matches!(error, PluginError::Io(io_error) if io_error.raw_os_error() == Some(30))
}

fn parse_permission_mode_arg(value: &str) -> Result<PermissionMode, String> {
    normalize_permission_mode(value)
        .ok_or_else(|| {
            format!(
