4. Integrate the orchestrator into the CLI flow (likely in `src/claw-cli/src/main.rs` where the REPL handles user prompts)

Here is the implementation:

```rust
// src/runtime/src/orchestrator.rs
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;

use crate::{
    ApiClient, ApiRequest, AssistantEvent, ConversationRuntime, PermissionMode,
    PermissionPolicy, Session, ToolExecutor, ToolError,
};
use api::ProviderClient;
use tools::GlobalToolRegistry;

/// Orchestrator that manages agent workflows for complex tasks
pub struct Orchestrator {
    /// Shared runtime configuration
    config: Arc<OrchestratorConfig>,
    /// Active agent jobs
    active_agents: Mutex<HashMap<String, AgentJobHandle>>,
}

struct OrchestratorConfig {
    /// Default models for different agent types
    model_routing: HashMap<AgentRole, String>,
    /// Maximum iterations per agent type
    max_iterations: HashMap<AgentRole, usize>,
    /// Allowed tools per agent type
    allowed_tools: HashMap<AgentRole, Vec<String>>,
    /// Permission policy for agents
    permission_policy: PermissionPolicy,
    /// System prompt templates
    system_prompts: HashMap<AgentRole, Vec<String>>,
}

/// Different agent roles the orchestrator can spawn
#[derive(Debug, Clone, Copy, Hash, Eq, PartialEq)]
pub enum AgentRole {
    Explorer,
    Architect,
    Coder,
    Frontend,
    Backend,
    Tester,
    Reviewer,
    Debugger,
}

struct AgentJobHandle {
    /// The agent's runtime
    runtime: ConversationRuntime<ProviderRuntimeClient, SubagentToolExecutor>,
    /// The agent's current session
    session: Session,
    /// Results from the agent's work
    result: Mutex<Option<String>>,
}

/// Simplified provider runtime client (adapted from existing code)
struct ProviderRuntimeClient {
    runtime: tokio::runtime::Runtime,
    client: ProviderClient,
    model: String,
    allowed_tools: GlobalToolRegistry,
}

impl ApiClient for ProviderRuntimeClient {
    fn stream(&mut self, request: ApiRequest) -> Result<Vec<AssistantEvent>, crate::RuntimeError> {
        // Simplified implementation - in reality would use the existing streaming logic
        let tools = self
            .allowed_tools
            .definitions(Some(&self.allowed_tools.entries().iter().map(|e| e.name.clone()).collect()))
            .into_iter()
            .map(|spec| api::ToolDefinition {
                name: spec.name.to_string(),
                description: Some(spec.description.to_string()),
                input_schema: spec.input_schema,
            })
            .collect::<Vec<_>>();

        let message_request = api::MessageRequest {
            model: self.model.clone(),
            max_tokens: super::super::api::max_tokens_for_model(&self.model),
            messages: super::super::convert_messages(&request.messages),
            system: (!request.system_prompt.is_empty()).then(|| request.system_prompt.join("\n\n")),
            tools: (!tools.is_empty()).then_some(tools),
            tool_choice: (!self.allowed_tools.entries().is_empty()).then_some(api::ToolChoice::Auto),
            stream: true,
        };

        self.runtime.block_on(async {
            let mut stream = self
                .client
                .stream_message(&message_request)
                .await
                .map_err(|e| crate::RuntimeError::new(e.to_string()))?;
            let mut events = Vec::new();
            let mut pending_tools: std::collections::BTreeMap<u32, (String, String, String)> =
                std::collections::BTreeMap::new();
            let mut saw_stop = false;

            while let Some(event) = stream
                .next_event()
                .await
                .map_err(|e| crate::RuntimeError::new(e.to_string()))?
            {
                match event {
                    api::ApiStreamEvent::MessageStart(start) => {
                        for block in start.message.content {
                            // Simplified - in reality would use push_output_block
                        }
                    }
                    api::ApiStreamEvent::ContentBlockStart(_) => {}
                    api::ApiStreamEvent::ContentBlockDelta(delta) => match delta.delta {
                        api::ContentBlockDelta::TextDelta { text } => {
                            if !text.is_empty() {
                                events.push(AssistantEvent::TextDelta(text));
                            }
                        }
                        api::ContentBlockDelta::InputJsonDelta { _ } => {}
                        api::ContentBlockDelta::ThinkingDelta { .. }
                        | api::ContentBlockDelta::SignatureDelta { .. } => {}
                    }
                    api::ApiStreamEvent::ContentBlockStop(_) => {}
                    api::ApiStreamEvent::MessageDelta(delta) => {
                        events.push(AssistantEvent::Usage(api::TokenUsage {
                            input_tokens: delta.usage.input_tokens,
                            output_tokens: delta.usage.output_tokens,
                            cache_creation_input_tokens: 0,
                            cache_read_input_tokens: 0,
                        }));
                    }
                    api::ApiStreamEvent::MessageStop(_) => {
                        saw_stop = true;
                        events.push(AssistantEvent::MessageStop);
                    }
                }
            }

            if !saw_stop
                && events.iter().any(|e| {
                    matches!(e, AssistantEvent::TextDelta(t) if !t.is_empty())
                        || matches!(e, AssistantEvent::ToolUse { .. })
                })
            {
                events.push(AssistantEvent::MessageStop);
            }

            if events.iter().any(|e| matches!(e, AssistantEvent::MessageStop)) {
                Ok(events)
            } else {
                let response = self
                    .client
                    .send_message(&api::MessageRequest {
                        stream: false,
                        ..message_request.clone()
                    })
                    .await
                    .map_err(|e| crate::RuntimeError::new(e.to_string()))?;
                Ok(crate::response_to_events(response))
            }
        })
    }
}

/// Simplified subagent tool executor (adapted from existing code)
struct SubagentToolExecutor {
