impl crate::ToolExecutor for SubagentToolExecutor {
    fn execute(&mut self, tool_name: &str, input: &str) -> Result<String, ToolError> {
        if !self.allowed_tools.entries().iter().any(|e| e.name == tool_name) {
            return Err(ToolError::new(format!(
                "tool `{tool_name}` is not enabled for this sub-agent"
            )));
        }
        let value = serde_json::from_str(input)
            .map_err(|e| ToolError::new(format!("invalid tool input JSON: {e}")))?;
        crate::execute_tool(tool_name, &value).map_err(ToolError::new)
    }
}

