    /// Execute a complex task by orchestrating multiple agents
    pub async fn execute_task(&self, task_description: &str) -> Result<String, String> {
        // 1. Decompose the task into subtasks for different agent roles
        let subtasks = self.decompose_task(task_description)?;

        // 2. Execute read-only agents in parallel (Explorer, Architect, etc.)
        let read_only_roles = vec![
            AgentRole::Explorer,
            AgentRole::Architect,
            // Add other read-only roles as needed
        ];

        let mut read_only_futures = Vec::new();
        for role in &read_only_roles {
            if let Some(subtask) = subtasks.get(role) {
                let orchestrator = self.clone();
                let fut = tokio::spawn(async move {
                    orchestrator.execute_agent_role(*role, subtask).await
                });
                read_only_futures.push(fut);
            }
        }

        // Wait for all read-only agents to complete
        let mut read_only_results = HashMap::new();
        for fut in read_only_futures {
            if let Ok(result) = fut.await {
                if let Ok((role, result)) = result {
                    read_only_results.insert(role, result);
                }
            }
        }

        // 3. Execute writing agents sequentially (Coder, Frontend, Backend)
        // In a real implementation, this would depend on the architecture from read-only agents
        let writing_roles = vec![AgentRole::Coder, AgentRole::Frontend, AgentRole::Backend];
        let mut writing_results = HashMap::new();
        for role in &writing_roles {
            if let Some(subtask) = subtasks.get(role) {
                // In reality, we would pass read_only_results as context
                let context = format!(
                    "Read-only agent results: {:#?}",
                    read_only_results
                );
                let enhanced_subtask = format!(
                    "{}\n\nContext from read-only agents:\n{}",
                    subtask, context
                );
                let orchestrator = self.clone();
                match orchestrator.execute_agent_role(*role, &enhanced_subtask).await {
                    Ok((role, result)) => {
                        writing_results.insert(role, result);
                    }
                    Err(e) => return Err(e),
                }
            }
        }

        // 4. Execute verification agents (Tester, Reviewer) in parallel
        let verification_roles = vec![AgentRole::Tester, AgentRole::Reviewer];
        let mut verification_futures = Vec::new();
        for role in &verification_roles {
            if let Some(subtask) = subtasks.get(role) {
                // In reality, we would pass writing results as context
                let context = format!(
                    "Writing agent results: {:#?}",
                    writing_results
                );
                let enhanced_subtask = format!(
                    "{}\n\nContext from writing agents:\n{}",
                    subtask, context
                );
                let orchestrator = self.clone();
                let fut = tokio::spawn(async move {
                    orchestrator.execute_agent_role(*role, &enhanced_subtask).await
                });
                verification_futures.push(fut);
            }
        }

        // Wait for all verification agents to complete
        let mut verification_results = HashMap::new();
        for fut in verification_futures {
            if let Ok(result) = fut.await {
                if let Ok((role, result)) = result {
                    verification_results.insert(role, result);
                }
            }
        }

        // 5. Synthesize final result from all agent outputs
        let final_result = self.synthesize_results(
            &read_only_results,
            &writing_results,
            &verification_results,
        )?;

        Ok(final_result)
    }

    /// Decompose a task into subtasks for different agent roles
    fn decompose_task(
        &self,
        task_description: &str,
    ) -> Result<HashMap<AgentRole, String>, String> {
        // In a real implementation, this would use an LLM to analyze the task
        // and break it down into subtasks for different roles
        // For now, we'll create a simple mapping
        let mut subtasks = HashMap::new();

        // Everyone gets the original task as a starting point
        for role in [
            AgentRole::Explorer,
            AgentRole::Architect,
            AgentRole::Coder,
            AgentRole::Frontend,
            AgentRole::Backend,
            AgentRole::Tester,
            AgentRole::Reviewer,
            AgentRole::Debugger,
        ] {
            subtasks.insert(role, task_description.to_string());
        }

        Ok(subtasks)
    }

    /// Execute a single agent role with a given subtask
    async fn execute_agent_role(
        &self,
        role: AgentRole,
        subtask: &str,
    ) -> Result<(AgentRole, String), String> {
        // Get configuration for this role
        let model = self
            .config
            .model_routing
            .get(&role)
            .cloned()
            .unwrap_or_else(|| "nvidia-agent".to_string());
        let max_iterations = *self
            .config
            .max_iterations
            .get(&role)
            .unwrap_or(&16);
        let allowed_tools = self
            .config
            .allowed_tools
            .get(&role)
            .cloned()
            .unwrap_or_else(|| Vec::new());
        let system_prompt = self
            .config
            .system_prompts
            .get(&role)
            .cloned()
            .unwrap_or_else(|| vec![]);

        // Create agent ID
        let agent_id = format!(
            "orchestrator-{role}-{}",
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs()
        );

        // Create session for this agent
        let session = Session::new();

        // Build the agent runtime
        let runtime = self.build_agent_runtime(
            session.clone(),
            model,
            allowed_tools,
            system_prompt,
            max_iterations,
        )?;

        // Run the agent on the subtask
        let summary = runtime
            .run_turn(subtask.to_string(), None)
            .map_err(|e| e.to_string())?;
        let result = crate::final_assistant_text(&summary);

        Ok((role, result))
    }

    /// Build a runtime for an agent with given parameters
    fn build_agent_runtime(
        &self,
        session: Session,
        model: String,
        allowed_tools: Vec<String>,
        system_prompt: Vec<String>,
        max_iterations: usize,
    ) -> Result<ConversationRuntime<ProviderRuntimeClient, SubagentToolExecutor>, String> {
        // Convert allowed_tools Vec<String> to GlobalToolRegistry
        let tool_registry = GlobalToolRegistry::with_plugin_tools(
            allowed_tools
                .iter()
                .map(|name| {
                    // In reality, we would look up the actual PluginTool
                    // For now, we'll use an empty vector and rely on built-in tools
                    tools::PluginTool::new(
                        "builtin".to_string(),
                        name.clone(),
                        tools::PluginToolDefinition {
                            name: name.clone(),
                            description: None,
                            input_schema: serde_json::json!({}),
                        },
                        "".to_string(),
                        Vec::new(),
                        tools::PluginToolPermission::DangerFullAccess,
                        None,
                    )
                })
                .collect(),
        )
        .map_err(|e| e)?;

        // Create the API client
        let api_client = ProviderRuntimeClient {
            runtime: tokio::runtime::Runtime::new().map_err(|e| e.to_string())?,
            client: api::ProviderClient::from_model(&model)
                .map_err(|e| e.to_string())?,
            model,
            allowed_tools: tool_registry.clone(),
        };

        // Create the tool executor
        let tool_executor = SubagentToolExecutor {
            allowed_tools: tool_registry,
        };

        // Build the runtime
        Ok(ConversationRuntime::new(
            session,
            api_client,
            tool_executor,
            self.config.permission_policy.clone(),
            system_prompt,
        ))
    }

    /// Synthesize results from all agents into a final answer
    fn synthesize_results(
        &self,
        read_only: &HashMap<AgentRole, String>,
        writing: &HashMap<AgentRole, String>,
        verification: &HashMap<AgentRole, String>,
    ) -> Result<String, String> {
        // In a real implementation, this would:
        // 1. Check for conflicts between agent outputs
        // 2. Use an LLM to synthesize a coherent answer
        // 3. Format the result appropriately
        // For now, we'll just concatenate the results
        let mut result = String::new();

        result.push_str("=== Orchestrator Task Results ===\n\n");

        if !read_only.is_empty() {
            result.push_str("Read-only Agent Results:\n");
            for (role, output) in read_only {
                result.push_str(&format!("{role:?}: {output}\n\n"));
            }
        }

        if !writing.is_empty() {
            result.push_str("Writing Agent Results:\n");
            for (role, output) in writing {
                result.push_str(&format!("{role:?}: {output}\n\n"));
            }
        }

        if !verification.is_empty() {
            result.push_str("Verification Agent Results:\n");
            for (role, output) in verification {
                result.push_str(&format!("{role:?}: {output}\n\n"));
            }
        }

        result.push_str("=== End of Results ===\n");
        Ok(result)
    }
}

